parameters.jsCode:
const full = Buffer.from($json.content, 'base64').toString('utf8');

// Только markdown-таблицы и их заголовки: «## Домены», «## Сущности» и строки,
// начинающиеся с «|». Комментарии <!-- --> и пояснительная проза отбрасываются.
//
// Таблицы, по которым решение принимает КОД, роутеру не нужны вовсе, и он
// за них платит токенами на каждом обращении. «Самостоятельные выгрузки» —
// это отчёты-трансформеры, их находит «Plan» по ключевым словам; «Маршруты» —
// эксперты по доменным темам, их находит он же. Модели по ним решать нечего:
// увидев их, она в лучшем случае повторит работу кода, в худшем — подставит
// id отчёта в plan.articles как путь к статье.
//
// Отбрасываются ПО ЗАГОЛОВКУ, а не по номеру секции: порядок разделов
// в index.md может поменяться, смысл заголовка — нет. Неизвестный заголовок
// остаётся: реестр растёт, и новая таблица должна доезжать до роутера
// по умолчанию, а не пропадать молча.
const CODE_ONLY = ['## Самостоятельные выгрузки', '## Маршруты'];
const keep = [];
let skip = false;
for (const raw of full.split('\n')) {
  const l = raw.trim();
  if (l.startsWith('##')) {
    skip = CODE_ONLY.includes(l);
    if (!skip) keep.push(l);
    continue;
  }
  if (skip) continue;
  if (l.startsWith('|')) { keep.push(l); continue; }
}
const compact = keep.join('\n');

// Проекция не должна оказаться пустой: формат index.md мог измениться.
// Пустой реестр — это молча неработающий роутер, поэтому в этом случае
// отдаём полный текст: дороже, но работает.
const text = compact.includes('|') ? compact : full;

return [{ json: { text, full, saved_chars: full.length - text.length } }];

// Разбор вывода роутера и построение плана чтения.
//
// Роутер отдаёт JSON. Модель иногда оборачивает его в ```json-заборы или
// добавляет слово перед ним, поэтому объект вырезается по первой «{» и
// последней «}», а не парсится целиком. Сбой разбора не роняет флоу: план
// остаётся пустым, автор получит материалы без статей и честно скажет, что
// в базе ответа нет. Молча превратить сбой в «бот не знает» нельзя — поэтому
// причина уходит в router_error и попадает в служебный блок лога.
const rawOut = String($json.output ?? $json.text ?? '').trim();

let plan = { domains: [], articles: [], dd: [], no_question: false };
let routerError = '';

// Предел числа объектов DD. Каждый объект — от одного до тринадцати HTTP-запросов
// внутри DD Lookup (карточка, список колонок, до 12 карточек колонок), поэтому
// четыре объекта это уже до 52 запросов. Обрезанное называется, а не режется
// молча — то же правило, что для статей.
const MAX_DD = 4;

try {
  const a = rawOut.indexOf('{');
  const b = rawOut.lastIndexOf('}');
  if (a === -1 || b <= a) throw new Error('в выводе роутера нет JSON-объекта');
  const got = JSON.parse(rawOut.slice(a, b + 1));
  plan.domains = Array.isArray(got.domains) ? got.domains.map(String) : [];
  plan.articles = Array.isArray(got.articles) ? got.articles.map(String) : [];
  plan.no_question = got.no_question === true;

  // Объекты DD. Основная форма — массив { urn, hint }.
  //
  // Скалярная форма { dd_urn, field_hint } тоже принимается: модель, увидев
  // старый пример или сбившись с формата, вернёт именно её, и терять из-за
  // этого метаданные целиком нельзя. Пустой инвентарь агент читает как
  // «полей нет» — ошибка тихая и потому дорогая.
  const rawDD = Array.isArray(got.dd)
    ? got.dd
    : typeof got.dd_urn === 'string' && got.dd_urn.trim()
      ? [{ urn: got.dd_urn, hint: got.field_hint }]
      : [];

  // Повтор URN СКЛЕИВАЕТ иглы, а не выбрасывает вторую.
  //
  // Раньше второй элемент с тем же URN отбрасывался целиком — «один объект
  // дважды это лишние запросы». Запросы и правда лишние, а вот игла нет:
  // вопрос «какое поле хранит логин и есть ли рабочая почта» — это один
  // объект и ДВА понятия. 2026-08-26 бот на нём уверенно ответил, что рабочей
  // почты в витрине нет; поля искали по одной игле «логин», а почту
  // не искали вовсе. Поле в витрине есть.
  // Объект по-прежнему один, запрос один — фильтр стал списком.
  const byUrnHints = new Map();
  for (const it of rawDD) {
    // Элемент может прийти и просто строкой-урном, без обёртки.
    const urn = String((it && typeof it === 'object' ? it.urn : it) ?? '').trim();
    if (!urn || urn === '—' || !urn.startsWith('urn:')) continue;
    const hint = String((it && typeof it === 'object' ? it.hint : '') ?? '').trim();
    if (!byUrnHints.has(urn)) byUrnHints.set(urn, []);
    const hints = byUrnHints.get(urn);
    // Пустая игла среди непустых бессмысленна: пустой фильтр означает
    // «отдай весь инвентарь», и рядом с конкретным словом он только
    // сбивает режим поиска. Дубли слов тоже ни к чему.
    if (hint && !hints.includes(hint)) hints.push(hint);
  }
  // Предел на число игл: фильтр из десяти слов совпадёт с половиной таблицы,
  // и «найдено по смыслу» перестанет что-либо сужать.
  const MAX_HINTS = 4;
  for (const [urn, hints] of byUrnHints) {
    plan.dd.push({ urn, hint: hints.slice(0, MAX_HINTS).join(', ') });
  }
} catch (e) {
  routerError = `не удалось разобрать план роутера: ${e.message}`;
}

// let, а не const: ниже сюда же дописывается то, что срезал повторный
// потолок после добора инвентаря прочитанных витрин.
const ddDropped = plan.dd.slice(MAX_DD).map((d) => d.urn);
plan.dd = plan.dd.slice(0, MAX_DD);

// Таблица «Домены» из реестра: домен → мастер-сущности. Мастерство — свойство
// пары «домен + сущность», поэтому берётся именно из этой таблицы, а не из
// строки сущности.
// Берём ПОЛНЫЙ текст, а не проекцию для промпта: разбор мастеров не должен
// зависеть от того, что и как проекция отфильтровала.
const reg = $('Decode registry').first().json;
const registry = String(reg.full ?? reg.text ?? '');

function rows(section, next) {
  const i = registry.indexOf(section);
  if (i === -1) return [];
  const j = next ? registry.indexOf(next, i) : -1;
  const chunk = registry.slice(i, j === -1 ? registry.length : j);
  return chunk
    .split('\n')
    .filter((l) => l.trim().startsWith('|'))
    .map((l) => l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim()))
    .filter((c) =>
      c.length > 1 && !/^-+$/.test(c[0]) &&
      c[0] !== 'домен' && c[0] !== 'id' && c[0] !== 'id отчёта' &&
      c[0] !== 'маршрут',
    );
}

const masters = new Map();          // домен → [id мастеров]
for (const c of rows('## Домены', '## Сущности')) {
  masters.set(c[0], String(c[2] || '').split(',').map((s) => s.trim()).filter(Boolean));
}

// Границей у «Сущности» ставим следующую секцию, а не конец файла: иначе
// таблица «Самостоятельные выгрузки» (свой формат колонок — id отчёта,
// ключевые слова) подмешается в разбор путей и dd_urn сущностей.
const byId = new Map();             // id сущности → путь к статье
const byUrn = new Map();            // id сущности → dd_urn (для отчётов без статьи)
const byTitle = new Map();          // id сущности → название, для сообщения автору
// Путь статьи → сама витрина. Нужна, чтобы код мог добрать инвентарь полей
// по прочитанной статье: живой прогон 2026-08-27 показал, что статью про
// витрину автор читает, а состав её полей — нет, и разницы между этим
// не делает ни он, ни код (см. ниже, «инвентарь витрин добирается кодом»).
const tableByPath = new Map();      // путь → {id, urn, title}
for (const c of rows('## Сущности', '## Самостоятельные выгрузки')) {
  const path = String(c[4] || '').trim();
  if (path && path !== '—') byId.set(c[0], path);
  const urn = String(c[5] || '').trim();
  if (urn && urn !== '—') byUrn.set(c[0], urn);
  byTitle.set(c[0], String(c[3] || '').trim());
  if (path && path !== '—' && urn && urn !== '—' && c[1] === 'table') {
    tableByPath.set(path, { id: c[0], urn, title: String(c[3] || '').trim() });
  }
}

// Мастера выбранных доменов — впереди остальных статей: автор читает материалы
// сверху вниз, и основание должно идти раньше частностей.
const ordered = [];
const seen = new Set();
const add = (p) => {
  if (p && p !== '—' && !seen.has(p)) { seen.add(p); ordered.push(p); }
};

// ------------------------------------------------ обязательные статьи выгрузки
//
// Тему обращения проставил ЧЕЛОВЕК в intake-форме — самый надёжный сигнал
// из всех доступных, надёжнее вывода модели. Поэтому для выгрузок плейбук
// и развилка «сотрудник или позиция» добираются КОДОМ, а не просьбой
// в промпте роутера («Запрос на выгрузку — всегда добавляй export-playbook»):
// живой прогон уже показывал, что словесные обязательства модель не держит,
// и ровно по этой причине мастеров домена добирает код.
//
// Цена пропуска здесь высокая и незаметная: без плейбука автор отвечает
// по существу вместо согласования, а без rc-structure-choice не задаёт
// вопрос про «сотрудники или все оформления» — и выгрузка выходит
// правдоподобной и неверной.
//
// Путь плейбука записан строкой: kb/process/ в таблице «Сущности» реестра
// не зарегистрирован вовсе, резолвить его по id неоткуда. Появится строка —
// заменить на резолв по id, как у развилки ниже. Если файла нет, «Build
// materials» скажет об этом вслух: реестр ссылается на несуществующий файл.
const trig0 = $('When called by adapter').first().json ?? {};
const question0 = String(trig0.question ?? '');

// Тема обращения. Основной источник — поле формы: его проставил человек.
// Но форму разбирает guard АДАПТЕРА, и знает её только канал: «Adapter Chat»
// передаёт topic_kind пустой строкой, а в личке формы нет вовсе. Поэтому тема
// восстанавливается ещё и из шапки самого обращения — в чат пост вставляют
// целиком, вместе с «Cross Data | Выгрузка данных от пользователя @X».
const head0 = question0.split('\n')[0].replace(/^[\s>*_#`~]+/, '').trim();
const topicKind = String(trig0.topic_kind ?? '') ||
  (/^cross data\s*\|/i.test(head0) ? head0 : '');

// Признак выгрузки считается по ТЕМЕ — своей или восстановленной из шапки,
// но не по всему тексту обращения. Слово «выгруз» встречается сплошь и в тех
// обращениях, где тему человек выбрал другую: «необходимо завести запрос
// на выгрузку» стоит в половине ответов по теме «Мне только спросить».
// Признак по тексту включал бы там весь режим: две лишние статьи, правила
// оформления в промпте автора и требование блока ТЗ. Тема остаётся сигналом
// человека, как и было.
//
// Живой прогон из чата 2026-08-17 показал, зачем здесь восстановление темы.
// Обращение было ровно про «Детальные списки» (нужны логины сотрудников
// юнита), а отчёт бот не предложил: topic_kind в чате пуст, isExport был
// false, и блок самообслуживания ниже не запускался вовсе. При этом «Build
// materials» режим выгрузки ВОССТАНАВЛИВАЛ по плейбуку среди прочитанного,
// и на выходе ядра стояло is_export: true — то есть по выходу отказ
// неотличим от нормальной работы. Асимметрия «у режима фолбэк есть,
// у поиска отчёта нет» и была причиной.
//
// Порядок files при этом остаётся диагностикой: при isExport плейбук
// и развилка идут ПЕРВЫМИ, а если плейбук пришёл последним — значит его
// выбрал роутер, а режим был выключен.
const isExport = /выгруз/i.test(topicKind);
const EXPORT_PATHS = ['kb/process/export-playbook.md'];
const EXPORT_IDS = ['rc-structure-choice'];

// Обращение про доступ. Тот же приём, что и с плейбуком выгрузки: статьи
// из kb/process/ НЕ заведены сущностями в реестре — у них нет ни dd_urn,
// ни домена, они описывают процесс, а не данные. Роутер их поэтому никогда
// не выберет, и добирать их приходится кодом по теме формы.
//
// Тема «Нет доступа к отчету» — одна из четырёх, по которым приходят
// обращения, и ответ на неё в базе должен быть. Пока routing.md со статусом
// draft и плейсхолдерами ‹…›, бот честно скажет, что значение не заполнено,
// а «Задача для базы» назовёт, что именно дописать. Это лучше, чем «в базе
// ответа нет»: видно, где ответ должен лежать.
//
// Здесь признак считается ТОЛЬКО по теме, без запасного признака по тексту —
// в отличие от выгрузки. Слово «доступ» стоит в самой форме выгрузки
// («Перечисли логины сотрудников, кому необходимо дать доступ к выгрузке»),
// и признак по тексту тянул бы статью маршрутизации в каждое обращение
// про выгрузку. Тема, восстановленная из шапки, работает и в чате.
const isAccess = /доступ/i.test(topicKind);
const ACCESS_PATHS = ['kb/process/routing.md'];

// Просят помочь НАПИСАТЬ ЗАПРОС — это вопрос аналитика, а не заявка на файл.
//
// Живой прогон 2026-08-27: «Можешь подсказать, как написать select, чтобы
// выгрузить сотрудника, его управленческий юнит и его юнит из функциональной
// структуры?» — и бот выдал согласование состава полей, три уточняющих
// вопроса и ТЗ для аналитика. То есть на просьбу написать запрос ответил
// «давайте сначала согласуем, что выгружаем», а SQL не написал: в режиме
// выгрузки он прямо запрещён.
//
// Режим включился не по теме — формы в чате нет вовсе, — а фолбэком
// «среди прочитанного есть плейбук выгрузки». Здесь и лежит развилка:
// тема из формы это ФАКТ, её проставил человек; восстановление по плейбуку
// это ДОГАДКА. Признак «просят запрос» перебивает догадку и не трогает факт,
// поэтому настоящая выгрузка со словом «select» в тексте режим не потеряет.
//
// Слово «выгруз» намеренно НЕ отменяет признак: «как написать select, чтобы
// выгрузить» — это ровно тот случай, ради которого всё и делается.
const QUERY_RE = /\b(?:select|sql|join)\b|как\s+(?:написать|составить|собрать|посчитать|вытащить|достать)|подскажи(?:те)?\s+(?:запрос|как)|какой\s+(?:джойн|join|запрос)|напиш(?:и|ите)\s+(?:запрос|select|sql)/i;
const isQueryHelp = QUERY_RE.test(question0);
// Статьи kb/process/ роутер не выбирает никогда — их нет в реестре, — поэтому
// конвенции запросов добираются кодом, как плейбук и маршрутизация. До этой
// правки sql-conventions.md не добирал НИКТО: файл лежал в базе и не доезжал
// до автора ни разу, то есть на вопрос про запрос у него не было ни одной
// статьи про то, как этот запрос положено писать.
const QUERY_PATHS = ['kb/process/sql-conventions.md'];

const addedExport = [];
if (isExport) {
  // Впереди мастеров домена: для выгрузки согласование и развилка витрины —
  // это основание, а численность и метрики — частности.
  for (const p of EXPORT_PATHS) { if (!seen.has(p)) addedExport.push(p); add(p); }
  for (const id of EXPORT_IDS) {
    const p = byId.get(id);
    if (p && !seen.has(p)) addedExport.push(p);
    add(p);
  }
}

const addedAccess = [];
if (isAccess) {
  for (const p of ACCESS_PATHS) { if (!seen.has(p)) addedAccess.push(p); add(p); }
}

const addedQuery = [];
if (isQueryHelp) {
  for (const p of QUERY_PATHS) { if (!seen.has(p)) addedQuery.push(p); add(p); }
}

// Отчёты для самостоятельной выгрузки: код ищет совпадение ключевых слов
// таблицы «Самостоятельные выгрузки» по ВСЕМУ тексту обращения — тот же
// принцип, что у мастеров домена и плейбука выгрузки: словесное обязательство
// («предложи самообслуживание, если подходит») модель не держит, поэтому
// кандидата находит код, а решение и формулировку оставляем автору.
// Совпадение ключевого слова — только сигнал «показать этот отчёт», а не
// гарантия покрытия: бот не видит инвентарь полей отчёта и не должен
// изображать, что сверил его с запросом.
// Гейт у подсказки про самообслуживание — свой, шире режима выгрузки: кроме
// темы принимается слово «выгруз» в тексте. В личке формы нет вовсе, человек
// пишет «нужна выгрузка логинов моей команды» — и не предложить ему готовый
// отчёт значит завести задачу на аналитика там, где он справился бы сам
// за минуту (в выгрузке канала таких случаев несколько, и все закрыты
// ответом «данные есть в Детальных списках»).
//
// Шире — но не бесплатно и не безобидно настолько, чтобы гейт снять вовсе:
// совпадение добавляет объект в DD Lookup (от одного до тринадцати запросов)
// и блок в материалы. Поэтому текст, где про выгрузку не сказано, отчёты
// не ищет: вопрос «где посмотреть табельный номер» — это вопрос по отчётам,
// у него свой маршрут, а не подсказка про самостоятельную выгрузку.
// Матчинг идёт по тексту, который написал ЧЕЛОВЕК, а не по служебному
// тексту формы. Haystack считается ОДИН раз и вне гейта самообслуживания:
// им пользуются и отчёты-трансформеры, и маршруты к экспертам, а гейты
// у них разные. Пока он жил внутри `if (selfServiceOn)`, второй потребитель
// получил бы либо пустую строку, либо копию правил чистки — а копия
// разъезжается молча, ровно как разъезжается список полей.
//
// Из haystack убирается:
//   шапка «Cross Data | … от пользователя @X»;
//   подписи полей — любая строка, кончающаяся двоеточием;
//   всё в круглых скобках.
//
// Скобки — главное здесь, и это НЕ то же самое, что «оставить значения
// полей». Прогон 2026-08-17: в обращении про логины юнита совпало
// единственное слово «фио», и не из подписи поля, а из ЗНАЧЕНИЯ —
// варианта выпадающего списка чувствительности «Персональные данные
// сотрудников (неполное ФИО, логин, раб. почта, возраст, master ID
// и др. внутренние ID)». Вариант этот одинаков во всех обращениях про ПДн,
// то есть отчёт предлагался бы по служебному тексту в каждом втором
// обращении. Ложное совпадение хуже промаха: предложение, которое
// появляется всегда, перестают читать.
//
// Правило про двоеточие здесь АГРЕССИВНЕЕ, чем LABEL_RE в guard'е адаптера
// (там ограничение в 60 символов). Причина в разной цене ошибки: guard
// обязан не потерять ЗНАЧЕНИЕ поля, а здесь надо не оставить ПОДПИСЬ, и
// подписи формы длинные — «Перечисли логины сотрудников, кому необходимо
// дать доступ к выгрузке:» это 69 символов и содержит слово «логин»,
// то есть под 60 символов не попадает и совпала бы в каждой выгрузке.
//
// Цена обоих правил: суть, написанная только внутри скобок или в строке
// с двоеточием на конце, не совпадёт. Это промах, а не ошибка — автор
// отвечает как обычно, просто без подсказки.
const haystack = question0
  .split('\n')
  .slice(/^cross data\s*\|/i.test(head0) ? 1 : 0)
  .map((l) => l.replace(/^[\s>*_#`~]+/, '').replace(/[\s*_`~]+$/, '').trim())
  .filter((l) => !l.endsWith(':'))
  .join('\n')
  .replace(/\([^)]*\)/g, ' ')
  .toLowerCase();

const MAX_SELF_SERVICE = 2;
const selfServiceAll = [];
const selfServiceOn = isExport || /выгруз/i.test(question0);
if (selfServiceOn) {
  // Граница — следующая секция, а не конец файла. Без неё строки таблицы
  // «Маршруты» (свой формат колонок) разобрались бы как отчёты: id взялся бы
  // из колонки «маршрут», ключевые слова — из своей, byTitle дал бы фолбэк
  // на сам id, и бот предлагал бы «самостоятельную выгрузку» под названием
  // «payroll». Ошибка ровно того класса, из-за которого граница уже стоит
  // у таблицы «Сущности».
  for (const c of rows('## Самостоятельные выгрузки', '## Маршруты')) {
    const id = c[0];
    const keywords = String(c[1] || '')
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean);
    const matched = keywords.filter((kw) => kw && haystack.includes(kw));
    if (matched.length) {
      selfServiceAll.push({
        id, title: byTitle.get(id) || id, urn: byUrn.get(id) || '',
        // По какому слову отчёт попал в материалы. Поле диагностическое:
        // ровно его не хватало, чтобы увидеть совпадение по служебному
        // тексту, — «отчёт предложен» и «отчёт предложен по слову из
        // подписи поля» по выходу ядра не отличались никак.
        matched: matched.slice(0, 3),
      });
    }
  }
}
const selfServiceDropped = selfServiceAll.slice(MAX_SELF_SERVICE).map((s) => s.id);
const selfService = selfServiceAll.slice(0, MAX_SELF_SERVICE);
for (const s of selfService) {
  if (s.urn && !plan.dd.some((d) => d.urn === s.urn)) plan.dd.push({ urn: s.urn, hint: '' });
}

// ------------------------------------------- маршруты к эксперту по теме
//
// В фидбеке аналитика за 14–26 августа 13 обращений из 49 решались тем, что
// дежурный звал эксперта по теме: ответа в базе на них нет и быть не может,
// а бот отвечал по витринам, потому что домен формально определялся.
//
// ЭТО НЕ «ОБРАЩЕНИЕ НЕ К НАМ». Часть экспертов — сотрудники CrossData:
// есть доменные области, где дежурный экспертизой не обладает, и по флоу
// зовётся тот, кто обладает; обращение при этом остаётся нашим. Часть
// адресатов действительно в других командах, но разделять их отдельным
// признаком незачем — действие одно и то же, и любая формулировка вида
// «это ведёт не наша команда» была бы неверной для половины строк таблицы.
//
// ГЕЙТА НЕТ, в отличие от самообслуживания. Причина простая: у отчётов-
// трансформеров гейт защищает от расхода (совпадение добавляет объект в DD
// Lookup, до тринадцати HTTP-запросов), а маршрут не стоит ничего — только
// строка в материалах. Зато тема у него любая: «кто ведёт квоты» приходит
// и вопросом, и выгрузкой, и в личку без формы вовсе.
//
// ЗАЩИТА ОТ ЛОЖНОГО СОВПАДЕНИЯ — не гейт, а сам список слов, и он выверен
// по выгрузке канала: маршрут срабатывает на 3 % строк (7 из 204), каждое
// срабатывание по адресу. Слова вроде «найм», «кандидат», «оклад», «рид»
// из списка выброшены именно по этой проверке — они били по нашим же
// обращениям. Правило записано над таблицей в kb/index.md: новое слово
// проверяется по выгрузке, потому что совпадение идёт ПОДСТРОКОЙ и на глаз
// это не видно («рид» внутри «гибрид», «оклад» внутри «доклад»).
//
// Эксперт НЕ заменяет ответ и НЕ трогает уверенность. Обратный порядок
// превратил бы бота в справочную «идите к такому-то» и обесценил его там,
// где он полезен; а понижение уверенности за найденного эксперта было бы
// прямо неверным — это дополнительное знание, а не пробел.
const MAX_ROUTES = 2;
const routesAll = [];
for (const c of rows('## Маршруты', null)) {
  // Строка признаётся маршрутом ПО ФОРМЕ, а не по тому, что лежит в секции:
  // пять колонок и дата в последней. В той же секции живёт пояснительная
  // таблица «какие слова выброшены и почему» — у неё две колонки, и без этой
  // проверки её строки разобрались бы маршрутами: «найм» стал бы id, а вся
  // фраза после него — списком ключевых слов. Прозу над таблицей правят чаще,
  // чем код, и разъезжается это молча.
  //
  // Строка без даты не сработает вовсе — и это осознанно. Валидатор базы
  // знаний (check_routes) на неё ругается громко, до коммита; парсер же
  // обязан не пустить в черновик маршрут, про который неизвестно, когда его
  // последний раз подтверждали. Тихо промолчать здесь дешевле, чем тихо
  // назвать уволившегося человека.
  if (c.length < 5 || !/^\d{4}-\d{2}-\d{2}$/.test(String(c[4] || '').trim())) continue;
  const keywords = String(c[1] || '')
    .split(',')
    .map((x) => x.trim().toLowerCase())
    .filter(Boolean);
  const matched = keywords.filter((kw) => kw && haystack.includes(kw));
  if (!matched.length) continue;
  const dash = (v) => { const t = String(v || '').trim(); return t === '—' ? '' : t; };
  routesAll.push({
    id: c[0],
    who: dash(c[2]),
    where: dash(c[3]),
    // Дата подтверждения едет вместе с именем и печатается ДЖУНУ.
    // Маршрут — утверждение про человека, и оно протухает молча: владельца
    // отчёта мы для этого и не дублируем в git, а берём онлайн из DD.
    // Здесь взять неоткуда — объекта «кто ведёт квоты» в каталоге нет, —
    // поэтому единственная защита это видимая дата. Без неё просроченный
    // маршрут работает до первого «он уволился полгода назад».
    checked: dash(c[4]),
    // По какому слову маршрут попал в материалы — то же диагностическое
    // поле, что у самообслуживания. Без него «маршрут найден» и «маршрут
    // найден по слову из шаблона формы» по выходу ядра неотличимы.
    matched: matched.slice(0, 3),
  });
}
const routesDropped = routesAll.slice(MAX_ROUTES).map((r) => r.id);
const routes = routesAll.slice(0, MAX_ROUTES);

// ВСЕ адресаты таблицы, а не только совпавшие. Нужны, чтобы поймать имя,
// названное в черновике без совпадения: живой прогон 2026-08-27 показал
// черновик, где бот подключил в тред человека из таблицы на вопросе, где
// ни одно ключевое слово маршрута не срабатывает. Неверное имя в треде —
// ошибка, видимая заказчику, и молчать о ней нельзя.
const routeNames = [];
for (const c of rows('## Маршруты', null)) {
  if (c.length < 5 || !/^\d{4}-\d{2}-\d{2}$/.test(String(c[4] || '').trim())) continue;
  for (const v of [c[2], c[3]]) {
    const t = String(v || '').trim();
    if (t && t !== '—') for (const one of t.split(',')) {
      const n = one.trim();
      if (n && !routeNames.includes(n)) routeNames.push(n);
    }
  }
}

// ------------------------------------ роутер не назвал НИЧЕГО: витрина по умолчанию
//
// Живой прогон 2026-08-27: «где взять инфу о количестве биай аналитиков
// в стриме дата 15 грейда в юните human capital origination». Роутер вернул
// пустые domains и пустые articles — значит мастера не добирались, читать
// было нечего, и бот честно ответил «нет ответа». А ответ в базе есть:
// это обычная численность с фильтрами по грейду, стриму и юниту, и считается
// она по мастер-витрине сотрудников.
//
// Пустой план — это отказ РОУТЕРА, а не пробел базы, и отвечать на него
// «нет ответа» значит выдавать одно за другое. Слова заказчика в таблице
// «Домены» дополнены по выгрузке канала (грейд, юнит, стрим, специализация,
// должность), но дыры у роутера будут всегда: догонять их словами — гонка
// без конца, а страховка нужна одна.
//
// ВИТРИНА ПО УМОЛЧАНИЮ ВЫВОДИТСЯ ИЗ РЕЕСТРА, а не вписана в сборщик:
// это сущность, назначенная мастером в наибольшем числе доменов. Своя
// константа здесь была бы четвёртым местом, где живёт одно знание, —
// и разъехалась бы молча, как разъезжается список полей. Тест держит
// вывод: если реестр изменится так, что умолчание переедет, он покраснеет
// и решение примет человек.
//
// Условие узкое намеренно: только когда роутер не дал НИ домена, НИ статьи.
// Одного домена достаточно, чтобы мастера добрались сами.
const addedFallback = [];
if (!plan.domains.length && !plan.articles.length && !plan.no_question) {
  const freq = new Map();
  for (const ids of masters.values()) {
    for (const id of ids) freq.set(id, (freq.get(id) || 0) + 1);
  }
  let best = '';
  let bestN = 0;
  for (const [id, n] of freq) {
    if (n > bestN) { best = id; bestN = n; }
  }
  const p = byId.get(best);
  if (p && !seen.has(p)) { addedFallback.push(best); add(p); }
}

const addedMasters = [];
for (const d of plan.domains) {
  for (const id of masters.get(d) || []) {
    const p = byId.get(id);
    if (p && !seen.has(p)) addedMasters.push(id);
    add(p);
  }
}
for (const p of plan.articles) add(p);

// Предохранитель на объём: 8 статей — это уже ~18k токенов материалов.
// Резать молча нельзя, поэтому обрезанное называется в служебном блоке.
const MAX_ARTICLES = 8;
const dropped = ordered.slice(MAX_ARTICLES);
const files = ordered.slice(0, MAX_ARTICLES);

// ------------------------------------- инвентарь прочитанных витрин: кодом
//
// Живой прогон 2026-08-27, обращение из инфобеза про телефоны подрядчиков.
// В служебном блоке стояло «метаданные: 1728» — то есть из каталога пришёл
// ровно ОДИН объект, отчёт, а инвентарь витрины mdm_employee_structure_d
// не запрашивался вообще. При этом в ТЗ бот написал: «в метаданных витрины
// mdm_employee_structure_d нет поля с мобильным телефоном». Утверждение
// о факте, которого он не видел; поле в каталоге есть.
//
// Отчёт попал в план кодом (таблица самообслуживания), а витрину должен был
// назвать роутер — и не назвал. Тот же класс, что мастера домена и плейбук
// выгрузки: словесное обязательство модель не держит, значит решение
// переезжает в код. Статья про витрину прочитана — её состав полей
// запрашивается, и это свойство конструкции, а не дисциплины роутера.
//
// ПУСТОЙ hint НАМЕРЕННО. Инвентарь без фильтра — это полный список имён
// полей одним запросом (289 имён ≈ 3 КБ), а не тринадцать запросов
// за описаниями. Дёшево и, главное, ПОЛНО: именно полнота здесь и была
// нужна — вопрос стоял «есть ли такое поле вообще». Угадывать фильтр
// за роутера было бы ровно тем угадыванием, от которого защищает
// документированное поведение «промах фильтра возвращает инвентарь».
// Если роутер этот же URN уже назвал со своим hint — не трогаем: его фильтр
// даёт ещё и описания, а пустой их не даёт.
// ГЕЙТ: только выгрузка и просьба помочь с запросом. Там состав полей —
// это то, из чего собирается ответ: ТЗ перечисляет поля поимённо, select
// их пишет. На вопрос «что такое текучесть» отвечает статья, а полный
// список из 289 имён был бы 3 КБ шума и расхода на КАЖДОМ обращении.
// Гейт тот же, что у sql-conventions, и по той же причине.
const needInventory = isExport || isQueryHelp;
const tablesRead = needInventory
  ? files.map((p) => tableByPath.get(p)).filter(Boolean)
  : [];
const addedDd = [];
for (const t of tablesRead) {
  if (plan.dd.some((d) => d.urn === t.urn)) continue;
  plan.dd.push({ urn: t.urn, hint: '' });
  addedDd.push(t.urn);
}
// Потолок применяется ЗАНОВО: добор мог его перебрать. Обрезанное
// приписывается к тому же ddDropped — режем не молча.
if (plan.dd.length > MAX_DD) {
  for (const d of plan.dd.slice(MAX_DD)) ddDropped.push(d.urn);
  plan.dd = plan.dd.slice(0, MAX_DD);
}

return [{
  json: {
    files,
    dropped,
    added_masters: addedMasters,
    // Режим выгрузки: определён по теме формы, то есть по сигналу человека.
    // Дальше по нему «Build materials» включает правила режима в промпт
    // автора, а «Parse answer» требует блок ТЗ. Одно решение — одно место.
    is_export: isExport,
    added_export: addedExport,
    // Обращение про доступ: своего режима у него нет, добирается только
    // статья процесса. Отдельным полем — чтобы в отчёте было видно, что
    // статью добрал код, а не выбрал роутер.
    is_access: isAccess,
    added_access: addedAccess,
    // Отчёты для самостоятельной выгрузки, найденные кодом по ключевым
    // словам. Пусто в режиме, отличном от выгрузки, — совпадение вне
    // is_export не проверяется вовсе, а не просто не показывается.
    self_service: selfService,
    self_service_dropped: selfServiceDropped,
    // Витрины, чьи СТАТЬИ уехали автору. «Build materials» сверяет этот
    // список с тем, по каким объектам инвентарь реально пришёл, и называет
    // разницу: статья прочитана, состав полей не получен — про такую витрину
    // утверждать отсутствие поля нельзя.
    tables_read: tablesRead,
    // Инвентарь, добранный кодом сверх плана роутера. Диагностическое поле:
    // без него «роутер назвал витрину» и «витрину добрал код» по выходу ядра
    // неотличимы, а это разные истории про качество роутера.
    dd_added_by_code: addedDd,
    // Просят помочь написать запрос. Отдельным полем, потому что читают его
    // двое: «Build materials» гасит по нему режим выгрузки, восстановленный
    // догадкой, а телеметрия считает, как часто такие обращения приходят.
    is_query_help: isQueryHelp,
    added_query: addedQuery,
    // Роутер не назвал ни домена, ни статьи — читалась витрина по умолчанию.
    // Отдельным полем: «роутер промахнулся» и «в базе нет ответа» это разные
    // вещи, и по выходу ядра они обязаны различаться. Оно же уезжает
    // в телеметрию — доля пустых планов это метрика качества роутера.
    added_fallback: addedFallback,
    // Эксперты по теме, найденные кодом. Пустой список — это «слов
    // маршрута в обращении нет», а не «маршрута не существует»: таблица
    // покрывает то, что встретилось в фидбеке, и растёт по мере трафика.
    routes,
    routes_dropped: routesDropped,
    route_names: routeNames,
    // Что роутер выбрал САМ, отдельно от итога.
    //
    // Пустой router_articles при непустом files значит «точного совпадения
    // в реестре не нашлось, читались только мастера домена по умолчанию».
    // Живой прогон 2026-08-11 показал, зачем это отличать: роутер не вернул
    // ни одной статьи, но назвал домен, код добрал трёх мастеров — и автор
    // уверенно ответил по материалам не про то, о чём спрашивали. Инвариант
    // «мастера читаются всегда» сработал, а оснований под ответом не было.
    // Прочерк и пустые строки отбрасываются: путь «—» в реестре означает
    // «статьи нет», и считать его выбором роутера — значит принять пробел
    // базы за совпадение.
    router_articles: plan.articles.filter((p) => p && p !== '—'),
    domains: plan.domains,
    dd: plan.dd,
    dd_dropped: ddDropped,
    // Число объектов вынесено отдельным полем: IF «Need DD» сравнивает его
    // с нулём. Условие по длине массива в n8n-выражении работает не везде
    // одинаково, а промах здесь тихий — метаданные просто не запросятся.
    dd_count: plan.dd.length,
    no_question: plan.no_question,
    router_error: routerError,
    router_raw: rawOut,
  },
}];

// Возвращает поля плана дальше по конвейеру, схлопывая поштучное чтение статей
// в один элемент. Сами тексты статей не тащим: их соберёт «Build materials»
// через $('Read article').all() — там же, где раскодировка base64.
const plan = $('Plan').first().json;
return [{ json: plan }];

// Материалы для автора: тексты прочитанных статей плюс метаданные DD.
//
// Режим ноды — «Run Once for All Items»: на входе все статьи, развёрнутые
